query:
mutation AddMapBranch($input: AddMapBranchInput!) {
  addMapBranch(input: $input) {
    added
    ids
  }
}

query BrandAnswers($first: Int = 20, $after: String, $ids: [ID!], $search: String) {
  brandAnswers(first: $first, after: $after, ids: $ids, search: $search) {
    nodes {
      id
      revision
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

mutation BrandChanges($input: BrandChangesInput!) {
  brandChanges(input: $input) {
    items {
      key
      status
      result
      error
    }
    instructions {
      code
      itemKey
      actor
      required
      message
      call
      taskId
      url
    }
  }
}

query BrandQuestions {
